<template><div class="app-container"><div class="head"><h2>移动记录仪</h2><div><el-button @click="load">刷新</el-button><el-button type="primary" @click="dialog=true">新增设备</el-button></div></div>
<el-table :data="items" border><el-table-column prop="deviceCode" label="设备编号"/><el-table-column prop="name" label="名称"/><el-table-column prop="vendor" label="厂商"/><el-table-column prop="model" label="型号"/><el-table-column prop="protocolType" label="协议"/><el-table-column prop="status" label="状态"/><el-table-column prop="batteryLevel" label="电量"/><el-table-column prop="networkStatus" label="网络"/><el-table-column label="能力" min-width="220"><template slot-scope="{row}"><el-tag v-for="v in caps(row)" :key="v" size="mini">{{v}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template slot-scope="{row}"><el-button size="mini" @click="location(row)">轨迹</el-button><el-button size="mini" type="primary" :disabled="!caps(row).includes('LIVE_VIDEO')" @click="preview(row)">预览</el-button></template></el-table-column></el-table>
<el-dialog title="新增记录仪" :visible.sync="dialog" width="500px"><el-form label-width="90px"><el-form-item label="设备编号"><el-input v-model="form.deviceCode"/></el-form-item><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="厂商"><el-input v-model="form.vendor"/></el-form-item><el-form-item label="型号"><el-input v-model="form.model"/></el-form-item><el-form-item label="协议"><el-select v-model="form.protocolType"><el-option label="厂商 SDK" value="VENDOR_SDK"/><el-option label="GB28181" value="GB28181"/><el-option label="通用" value="GENERIC"/></el-select></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">保存</el-button></span></el-dialog>
<el-dialog title="定位轨迹" :visible.sync="locationDialog"><el-table :data="locations"><el-table-column prop="locateTime" label="时间"/><el-table-column prop="longitude" label="经度"/><el-table-column prop="latitude" label="纬度"/><el-table-column prop="accuracyMeters" label="精度(米)"/></el-table></el-dialog></div></template>
<script>import{ mobileRecorders, createMobileRecorder, recorderLocations, acquireRecorderStream }from'@/api/inspection';const d=v => (v&&v.data)||v||[];export default{ name:'RecorderManagement', data:() => ({ items:[], locations:[], dialog:false, locationDialog:false, form:{ protocolType:'VENDOR_SDK' } }), created(){this.load()}, methods:{ caps(r){return(r.capabilities||'').split(',').filter(Boolean)}, async load(){this.items=d(await mobileRecorders())}, async create(){await createMobileRecorder(this.form);this.dialog=false;this.form={ protocolType:'VENDOR_SDK' };this.load()}, async location(r){this.locations=d(await recorderLocations(r.id));this.locationDialog=true}, async preview(r){const x=await acquireRecorderStream(r.id);this.$message.success(`并发租约已获取，有效至 ${(x.data||x).expiresAt}`)} } }</script><style scoped>.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.head h2{margin:0}.el-tag{margin:2px}</style>
